                if(accumulator > 0) {

                    atomicAdd(&(histo_s[prevBinIdx]), accumulator);

                }

                accumulator = 1;

                prevBinIdx = bin;

            }

        }

    }

    if(accumulator > 0) {

        atomicAdd(&(histo_s[prevBinIdx]), accumulator);

    }

    __syncthreads();

    // Commit to global memory

    for(unsigned int bin = threadIdx.x; bin<NUM_BINS; bin += blockDim.x) {

        unsigned int binValue = histo_s[bin];

        if(binValue > 0) {

            atomicAdd(&(histo[bin]), binValue);

