__global__ void bfs_kernel(CSRGraph csrGraph, unsigned int* level,

                        unsigned int* newVertexVisited, unsigned int currLevel) {

    unsigned int vertex = blockIdx.x*blockDim.x + threadIdx.x;

    if(vertex < csrGraph.numVertices) {

