void convLayer_forward(int M, int C, int H, int W, int K, float* X, float* W,

                     float* Y) {

    int H_out = H - K + 1;

    int W_out = W - K + 1;

    for(int m = 0;  m < M;  m++)        // for each output feature map

        for(int h = 0; h < H_out; h++)    // for each output element

            for(int w = 0; w < W_out; w++) {

